import'./cloud-sync.js';import{FACTOR_TRACKS,FACTOR_CHAIN,FACTOR_DIAGNOSTIC,recommendFactorTrack,factorPairs,isPrime,createBlankFactorLearner}from'./factors-data.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],key='mathlab-factors-v1';function blank(){return{a:createBlankFactorLearner(),b:createBlankFactorLearner(),learner:'a'}}function read(){try{return JSON.parse(localStorage.getItem(key))||blank()}catch{return blank()}}let store=read(),learner=store.learner||'a',state=store[learner]||createBlankFactorLearner(),attempts=0,hints=0,sessionId=null;const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function ensure(){const b=createBlankFactorLearner();state={...b,...state,diagnostic:{...b.diagnostic,...state.diagnostic},missions:{...state.missions},sessions:{...state.sessions},evidence:{...b.evidence,...state.evidence},family:{...b.family,...state.family}}}function save(){state.updatedAt=new Date().toISOString();store={...read(),[learner]:state,learner};localStorage.setItem(key,JSON.stringify(store));$('#saveStatus').textContent='Saved offline · cloud sync follows parent sign-in'}function track(){return FACTOR_TRACKS[state.track||'explorer']}function done(i){return!!state.missions[FACTOR_CHAIN.missions[i].id]?.complete}function unlocked(i){return i===0||done(i-1)}function feedback(t,c=''){$('#feedback').textContent=t;$('#feedback').className='feedback '+c}
function load(id){sessionId=id;const x=state.sessions[id]||{attempts:0,hints:0,stage:0};attempts=x.attempts||0;hints=x.hints||0;return x}function session(stage){state.sessions[sessionId]={attempts,hints,stage};save()}function mark(k,ok){if(ok)state.evidence[k]='independent';else if(state.evidence[k]==='unknown')state.evidence[k]='learning'}function complete(i,dims=[],pending=false,preview=false){const m=FACTOR_CHAIN.missions[i],ind=attempts===0&&hints===0&&!preview;state.missions[m.id]={complete:!preview,preview,attempts,hints,track:state.track,completedAt:new Date().toISOString()};dims.forEach(x=>mark(x,ind));if(pending)state.retestDue=Date.now()+20*60*60*1000;if(!preview&&i<4)state.activeMission=i+1;if(sessionId)delete state.sessions[sessionId];sessionId=null;attempts=hints=0;save();setTimeout(render,350)}function tried(ok){if(!ok)attempts++;session(state.sessions[sessionId]?.stage||0)}function hint(t){return hints?`<div class="hint-box">${esc(t)}</div>`:''}function controls(){return'<div class="answer-row"><button class="secondary" data-action="hint">Give me one hint</button></div>'}function options(items,right,pos,attr){const a=items.map((x,i)=>({x,ok:i===right})),r=a.splice(right,1)[0];a.splice(pos,0,r);return a.map(o=>`<button class="choice" data-${attr}="${o.ok?'correct':'wrong'}">${esc(o.x)}</button>`).join('')}
function renderDiagnostic(){const d=state.diagnostic;if(d.index===3){state.track=state.track||recommendFactorTrack(d.score);const t=track();$('#activity').innerHTML=`<div class="complete-card"><div class="big-check">✓</div><p class="eyebrow">STARTING DEPTH FOUND</p><h3>${t.label}</h3><p>${t.description}</p><button class="primary" data-action="start">Build factor pairs →</button></div>`;return}const q=FACTOR_DIAGNOSTIC[d.index];$('#activity').innerHTML=`<p class="eyebrow">QUESTION ${d.index+1} OF 3</p><h3>${q.prompt}</h3><div class="answer-grid">${q.choices.map(x=>`<button class="choice" data-diag="${esc(x)}">${esc(x)}</button>`).join('')}</div><p class="microcopy">No timer. A multiplication fact can be your evidence.</p>`;$$('[data-diag]').forEach(b=>b.onclick=()=>{if(b.disabled)return;$$('[data-diag]').forEach(x=>x.disabled=true);const ok=b.dataset.diag===q.answer;d.answers.push({id:q.id,correct:ok});if(ok)d.score++;d.index++;feedback(ok?'Yes. The multiplication relationship proves it.':q.why,ok?'good':'try');save();setTimeout(render,450)})}
function renderPairs(){const t=track(),p=t.pairs,x=state.sessions[sessionId]||{stage:0};if(!x.stage){$('#activity').innerHTML=`<p class="eyebrow">TEST A PAIR</p><h3>Which pair makes ${p.n}?</h3><p class="prompt">Both numbers must be whole numbers, and their product must equal ${p.n}.</p><div class="answer-grid">${options([p.pick,...p.pickWrong],0,t.pos,'pair')}</div>${controls()}${hint(`Multiply each pair. A factor pair must land exactly on ${p.n}.`)}`;$$('[data-pair]').forEach(b=>b.onclick=()=>{const ok=b.dataset.pair==='correct';tried(ok);if(ok){session(1);renderMission()}else feedback(`That pair does not multiply to ${p.n}.`,'try')});return}$('#activity').innerHTML=`<p class="eyebrow">SEARCH IN ORDER</p><h3>Which list contains every factor pair of ${p.n}?</h3><p class="prompt">Start with 1 and test in order. Stop when the pair repeats in reverse.</p><div class="factor-pair-card"><strong>${factorPairs(p.n).length} pair${factorPairs(p.n).length===1?'':'s'} to find</strong><span>No gaps. No pair twice.</span></div><div class="answer-grid">${options([p.all,...p.allWrong],0,(t.pos+1)%3,'allpairs')}</div>${controls()}${hint('Test 1, 2, 3, and so on. Once the two factors meet or cross, later pairs repeat in reverse.')}`;$$('[data-allpairs]').forEach(b=>b.onclick=()=>{const ok=b.dataset.allpairs==='correct';tried(ok);if(ok){feedback('Complete. Every factor pair appears once, in order.','good');complete(1,['pairs','completeSearch'])}else feedback('One pair is missing or one product does not equal the target.','try')})}
function specialNumbers(){return'<div class="special-number-card"><strong>Two special numbers</strong><span><b>1</b> has only one positive factor, so it is neither prime nor composite.</span><span><b>2</b> has exactly two positive factors, so it is prime—the only even prime.</span></div>'}
function renderClassify(){const t=track(),p=t.classify,x=state.sessions[sessionId]||{stage:0};if(!x.stage){const correct=p.type[0].toUpperCase()+p.type.slice(1);$('#activity').innerHTML=`<p class="eyebrow">CLASSIFY FROM FACTORS</p><h3>Is ${p.n} prime or composite?</h3>${specialNumbers()}<p class="prompt">Prime means exactly two positive factors: 1 and the number itself. Composite means more than two.</p><div class="answer-grid">${options([correct,correct==='Prime'?'Composite':'Prime','Neither'],0,t.pos,'classify')}</div>${controls()}${hint(`Search for a whole-number factor pair besides 1 × ${p.n}.`)}`;$$('[data-classify]').forEach(b=>b.onclick=()=>{const ok=b.dataset.classify==='correct';tried(ok);if(ok){session(1);renderMission()}else feedback('Use the number of positive factors, not whether the number looks odd or even.','try')});return}if(x.stage===1){$('#activity').innerHTML=`<p class="eyebrow">SHOW A COMPLETE SEARCH</p><h3>Which search is enough to classify ${p.n}?</h3><p class="prompt">Test possible small factors in order. For a composite number, you may stop when one exact pair is found. For a prime, continue until the two factors would meet or cross.</p><div class="answer-grid">${options([p.search,...p.wrongSearches],0,(t.pos+2)%3,'classsearch')}</div>${controls()}${hint('Do not stop after one failed test. Keep checking in order until a factor is found or later pairs would only repeat.')}`;$$('[data-classsearch]').forEach(b=>b.onclick=()=>{const ok=b.dataset.classsearch==='correct';tried(ok);if(ok){session(2);renderMission()}else feedback('That search stops too early or uses appearance instead of factors.','try')});return}$('#activity').innerHTML=`<p class="eyebrow">PROVE THE CLASSIFICATION</p><h3>Which conclusion follows from the complete search?</h3><div class="answer-grid">${options([p.proof,...p.wrongProofs],0,(t.pos+1)%3,'classproof')}</div>${controls()}${hint('A proof must name what the complete factor search found.')}`;$$('[data-classproof]').forEach(b=>b.onclick=()=>{const ok=b.dataset.classproof==='correct';tried(ok);if(ok){feedback('Proved. The conclusion follows from your complete factor search.','good');complete(2,['classification','completeSearch'])}else feedback('Choose the conclusion supported by the complete factor search.','try')})}
function renderRepair(){const t=track(),p=t.repair,x=state.sessions[sessionId]||{stage:0};if(!x.stage){$('#activity').innerHTML=`<p class="eyebrow">QUESTION THE CLAIM</p><h3>“${p.claim}”</h3><p class="prompt">Why is this reasoning unreliable?</p><div class="answer-grid">${options([p.cause,...p.wrongProofs],0,(t.pos+2)%3,'cause')}</div>${controls()}${hint('Look for a factor pair that supports or breaks the claim.')}`;$$('[data-cause]').forEach(b=>b.onclick=()=>{const ok=b.dataset.cause==='correct';tried(ok);if(ok){session(1);renderMission()}else feedback('A useful diagnosis explains exactly what the claim failed to test.','try')});return}$('#activity').innerHTML=`<p class="eyebrow">BUILD A COUNTEREXAMPLE</p><h3>Which evidence repairs the claim?</h3><div class="repair-card"><span>Faulty claim</span><strong>${p.claim}</strong></div><div class="answer-grid">${options([p.proof,...p.wrongProofs],0,t.pos,'repair')}</div>${controls()}${hint('A counterexample is one exact case that makes a broad claim fail.')}`;$$('[data-repair]').forEach(b=>b.onclick=()=>{const ok=b.dataset.repair==='correct';tried(ok);if(ok){feedback('Repaired. One exact factor relationship defeats the faulty claim.','good');complete(3,['counterexample','classification'],true)}else feedback('Check the multiplication. The evidence must directly answer the claim.','try')})}
function renderFresh(){const due=state.retestDue||Date.now()+72000000,ready=Date.now()>=due,previewDone=state.missions[FACTOR_CHAIN.missions[4].id]?.preview;if(!ready&&previewDone){$('#activity').innerHTML=`<div class="complete-card"><div class="big-check">✓</div><p class="eyebrow">FAMILY PREVIEW COMPLETE</p><h3>Your factor proof worked.</h3><p>This preview did not count as fresh evidence. Return after the wait for a new number.</p><a class="primary" href="./">Return home</a></div>`;return}if(!ready&&!state.previewFresh){$('#activity').innerHTML=`<div class="lock-card"><p class="eyebrow">FRESH CHECK</p><strong>Return after the method has faded.</strong><p>A new number checks what truly stayed.</p><button class="secondary" data-action="preview">Preview for family review</button></div>`;return}const mode=ready?'challenge':'preview',sid=`factor-transfer:${mode}`;if(sessionId!==sid)load(sid);const t=track(),p=t.fresh[mode],x=state.sessions[sessionId]||{stage:0},correct=p.type[0].toUpperCase()+p.type.slice(1);if(!x.stage){$('#activity').innerHTML=`<p class="eyebrow">${ready?'DELAYED CHECK · NEW NUMBER':'FAMILY PREVIEW · NO DELAYED EVIDENCE'}</p><h3>Is ${p.n} prime or composite?</h3>${specialNumbers()}<div class="answer-grid">${options([correct,correct==='Prime'?'Composite':'Prime','Neither'],0,p.pos,'freshclass')}</div>${controls()}${hint('Search systematically for a whole-number factor pair.')}`;$$('[data-freshclass]').forEach(b=>b.onclick=()=>{const ok=b.dataset.freshclass==='correct';tried(ok);if(ok){session(1);renderMission()}else feedback('Classify from the factors, then prove it.','try')});return}if(x.stage===1){$('#activity').innerHTML=`<p class="eyebrow">${ready?'DELAYED SEARCH':'PREVIEW SEARCH'}</p><h3>Which search is complete enough for ${p.n}?</h3><div class="answer-grid">${options([p.search,...p.wrongSearches],0,(p.pos+1)%3,'freshsearch')}</div>${controls()}${hint('Test possible factors in order. Stop only after finding an exact pair or reaching the point where pairs repeat.')}`;$$('[data-freshsearch]').forEach(b=>b.onclick=()=>{const ok=b.dataset.freshsearch==='correct';tried(ok);if(ok){session(2);renderMission()}else feedback('That search stops too early or replaces evidence with a number pattern.','try')});return}$('#activity').innerHTML=`<p class="eyebrow">${ready?'DELAYED PROOF':'PREVIEW PROOF'}</p><h3>Which conclusion follows from that complete search?</h3><div class="answer-grid">${options([p.proof,`It is ${p.n%2?'odd':'even'}, so the label must be right.`,`It is close to ${Math.round(p.n/10)*10}, so the label must be right.`],0,p.proofPos,'freshproof')}</div>${controls()}${hint('The proof must use what the complete factor search found.')}`;$$('[data-freshproof]').forEach(b=>b.onclick=()=>{const ok=b.dataset.freshproof==='correct';tried(ok);if(ok){const independent=attempts===0&&hints===0;feedback(ready?(independent?'Fresh transfer shown. You classified and proved a new number independently.':'Fresh practice complete. You used feedback or a hint, so this is saved as learning evidence.'):'Preview complete. Return later for fresh evidence.','good');complete(4,ready?['completeSearch','classification','transfer']:[],false,!ready)}else feedback('A proof must follow from the complete factor search.','try')})}
function renderComplete(i){const m=FACTOR_CHAIN.missions[i];$('#activity').innerHTML=`<div class="complete-card"><div class="big-check">✓</div><p class="eyebrow">MISSION COMPLETE</p><h3>${m.title}</h3><p>Your work is saved for ${learner==='a'?'Ella':'Mila'}.</p>${i<4?'<button class="primary" data-action="next">Continue →</button>':'<a class="primary" href="./">Return home</a>'}</div>`}
function renderMission(){const i=state.activeMission,m=FACTOR_CHAIN.missions[i];if(i!==4&&sessionId!==m.id)load(m.id);$('#missionEyebrow').textContent=`MISSION ${m.number} · ${m.kind.toUpperCase()}`;$('#missionTitle').textContent=m.title;$('#missionObjective').textContent=m.objective;$('#missionTime').textContent=`ABOUT ${m.minutes} MIN`;feedback('');if(done(i))renderComplete(i);else if(i===0)renderDiagnostic();else if(i===1)renderPairs();else if(i===2)renderClassify();else if(i===3)renderRepair();else renderFresh()}
function renderNav(){$('#missionNav').innerHTML=FACTOR_CHAIN.missions.map((m,i)=>`<button class="mission-button ${i===state.activeMission?'active':''}" data-mission="${i}" ${unlocked(i)?'':'disabled'}><span class="mission-number">${m.number}</span><span class="mission-label">${m.title}</span><span class="mission-state">${done(i)?'✓':unlocked(i)?'›':'◌'}</span></button>`).join('');$$('[data-mission]').forEach(b=>b.onclick=()=>{state.activeMission=+b.dataset.mission;sessionId=null;save();render()})}function renderTrack(){const t=track();$('#trackCard').innerHTML=`<strong>Current depth: ${t.label}</strong><span>${t.description}</span><select id="trackSelect" aria-label="Learning depth">${Object.values(FACTOR_TRACKS).map(x=>`<option value="${x.id}" ${x.id===t.id?'selected':''}>${x.label}</option>`).join('')}</select><small>Changing depth restarts this review path.</small>`;$('#trackSelect').onchange=e=>{state={...createBlankFactorLearner(),track:e.target.value,family:state.family};sessionId=null;save();render()}}function renderEvidence(){const labels={pairs:'Factor pairs',completeSearch:'Complete search',classification:'Prime or composite proof',counterexample:'Counterexample reasoning',transfer:'Fresh transfer'};$('#evidenceGrid').innerHTML=Object.entries(labels).map(([k,v])=>`<div><span>${v}</span><strong class="${state.evidence[k]}">${state.evidence[k]}</strong></div>`).join('');$('#evidenceTitle').textContent=`${learner==='a'?'Ella':'Mila'}’s learning evidence`}
function wire(){const a=x=>$(`[data-action="${x}"]`);if(a('start'))a('start').onclick=()=>complete(0);if(a('next'))a('next').onclick=()=>{state.activeMission++;save();render()};if(a('hint'))a('hint').onclick=()=>{hints++;session(state.sessions[sessionId]?.stage||0);renderMission()};if(a('preview'))a('preview').onclick=()=>{state.previewFresh=true;save();render()}}function render(){ensure();renderNav();renderTrack();renderEvidence();renderMission();wire();$('#helpNote').value=state.family.help||'';$('#explainNote').value=state.family.explain||'';$('#continueNote').value=state.family.continue||''}$('#learnerSelect').value=learner;$('#learnerSelect').onchange=e=>{learner=e.target.value;store=read();store.learner=learner;state=store[learner]||createBlankFactorLearner();sessionId=null;save();render()};['helpNote','explainNote','continueNote'].forEach(id=>$('#'+id).onchange=e=>{state.family[id==='helpNote'?'help':id==='explainNote'?'explain':'continue']=e.target.value;save()});$('#resetPath').onclick=()=>{if(confirm('Reset this learner’s factor path?')){state=createBlankFactorLearner();sessionId=null;save();render()}};render();
